import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"Translation Options","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/translation-options.md","filePath":"en/guide/translation-options.md"}`),a={name:`en/guide/translation-options.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="translation-options" tabindex="-1">Translation Options <a class="header-anchor" href="#translation-options" aria-label="Permalink to “Translation Options”">​</a></h1><p>This page describes Zotero PDF2zh <strong>v4.1.1</strong> (including v4.1.0 features).</p><p>Select a paper item or PDF attachment in Zotero, then open the <strong>PDF2zh</strong> context menu.</p><p>v4.1.0 tracks the current PDF operation state so already-processed files are not sent into incompatible operations again.</p><h2 id="pdf-states" tabindex="-1">PDF States <a class="header-anchor" href="#pdf-states" aria-label="Permalink to “PDF States”">​</a></h2><p>A typical flow is:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>origin</span></span>
<span class="line"><span>→ mono / dual(LR/TB)</span></span>
<span class="line"><span>→ mono-cut / dual-cut / compare / crop-compare</span></span></code></pre></div><p><code>compare</code> and <code>crop-compare</code> are terminal results. Repeating the same operation on a terminal file is blocked before upload.</p><h2 id="translate-pdf" tabindex="-1">Translate PDF <a class="header-anchor" href="#translate-pdf" aria-label="Permalink to “Translate PDF”">​</a></h2><p><strong>Input:</strong> original PDF / paper item.</p><p>Generates mono, dual, and any additional outputs enabled in plugin settings.</p><p>Running Translate PDF on an already generated mono / dual / compare / crop-compare attachment is rejected. Select the original attachment when you want to translate again.</p><h2 id="crop-pdf" tabindex="-1">Crop PDF <a class="header-anchor" href="#crop-pdf" aria-label="Permalink to “Crop PDF”">​</a></h2><p><strong>Supported input:</strong></p><ul><li>origin</li><li>mono</li><li>dual</li></ul><p>Typical output:</p><ul><li><code>mono-cut</code></li><li><code>dual-cut</code></li></ul><p>For a <code>pdf2zh_next</code> <strong>LR dual</strong> (side-by-side), v4.1.0 first normalizes the layout internally, then continues through the real crop operation:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LR dual</span></span>
<span class="line"><span>→ internal LR→TB normalization</span></span>
<span class="line"><span>→ actual crop</span></span>
<span class="line"><span>→ dual-cut</span></span></code></pre></div><p>The internal layout conversion is no longer mistaken for the final Crop result.</p><h2 id="compare-pdf" tabindex="-1">Compare PDF <a class="header-anchor" href="#compare-pdf" aria-label="Permalink to “Compare PDF”">​</a></h2><p><strong>Supported input:</strong></p><ul><li>origin</li><li>dual</li></ul><p>Output: <code>compare</code>.</p><p>When the input is an original PDF, the Server first generates the required dual PDF and then builds the compare result.</p><p><code>compare</code> is terminal; running Compare on an existing compare result is blocked.</p><h2 id="crop-compare-pdf" tabindex="-1">Crop-Compare PDF <a class="header-anchor" href="#crop-compare-pdf" aria-label="Permalink to “Crop-Compare PDF”">​</a></h2><p><strong>Supported input:</strong></p><ul><li>origin</li><li>dual</li><li>dual-cut</li></ul><p>This is intended for two-column papers: normalize/crop to a single-column structure and then generate the bilingual comparison result.</p><p>For an LR dual:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LR dual</span></span>
<span class="line"><span>→ internal LR→TB normalization</span></span>
<span class="line"><span>→ actual crop-compare</span></span>
<span class="line"><span>→ crop-compare</span></span></code></pre></div><p>v4.1.0 fixes the old behavior where the first Crop-Compare could stop after the LR→TB conversion while naming that intermediate file as a crop-compare result.</p><p><code>crop-compare</code> is also terminal. The plugin and Server both reject a repeated Crop-Compare operation.</p><h2 id="what-are-lr-and-tb" tabindex="-1">What are LR and TB? <a class="header-anchor" href="#what-are-lr-and-tb" aria-label="Permalink to “What are LR and TB?”">​</a></h2><h3 id="lr-side-by-side" tabindex="-1">LR / Side by Side <a class="header-anchor" href="#lr-side-by-side" aria-label="Permalink to “LR / Side by Side”">​</a></h3><p>Original and translated content share one page side by side.</p><h3 id="tb-alternating-pages" tabindex="-1">TB / Alternating Pages <a class="header-anchor" href="#tb-alternating-pages" aria-label="Permalink to “TB / Alternating Pages”">​</a></h3><p>Original and translated pages alternate.</p><div class="info custom-block"><p class="custom-block-title">Historical label</p><p>Older UI/docs called TB “Top &amp; Bottom”. In current <code>pdf2zh_next</code> / BabelDOC behavior it means <strong>Alternating Pages</strong>, not a vertical same-page layout.</p></div><h2 id="when-should-i-return-to-the-original-pdf" tabindex="-1">When should I return to the original PDF? <a class="header-anchor" href="#when-should-i-return-to-the-original-pdf" aria-label="Permalink to “When should I return to the original PDF?”">​</a></h2><p>Return to the original PDF (or the original dual result) when you want to:</p><ul><li>change model or language;</li><li>change Thinking settings;</li><li>generate another layout;</li><li>rebuild a terminal compare / crop-compare result.</li></ul><p>Avoid repeatedly chaining post-processing operations on an already processed result.</p><h2 id="batch-processing" tabindex="-1">Batch Processing <a class="header-anchor" href="#batch-processing" aria-label="Permalink to “Batch Processing”">​</a></h2><p>Multiple items or attachments can be selected and processed together.</p><p>v4.1.0 fixes batch accounting: a failed file is counted in <code>failed</code> instead of being swallowed and reported as success, and the temporary batch event listener is removed after completion.</p><h2 id="recommended-operation" tabindex="-1">Recommended Operation <a class="header-anchor" href="#recommended-operation" aria-label="Permalink to “Recommended Operation”">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Recommended action</th></tr></thead><tbody><tr><td>Normal translation</td><td>Translate PDF</td></tr><tr><td>Single-column/mobile reading</td><td>Crop</td></tr><tr><td>Original/translation comparison</td><td>Compare</td></tr><tr><td>Two-column paper with cropped comparison</td><td>Crop-Compare</td></tr><tr><td>Rebuild an existing terminal result</td><td>Return to original/dual and regenerate</td></tr></tbody></table><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><a href="/en/guide/configuration.html">Configuration</a></li><li><a href="/en/guide/installation.html">Installation</a></li><li><a href="/en/guide/package-update.html">Translation Environment Updates</a></li></ul>`,51)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};